python3 - <<'PY'
import pathlib
p = pathlib.Path("src/codegen/lower_inst/exceptions.rs")
s = p.read_text()
old = "    inst: &Instruction,\n    frame_name: &str,"
new = "    inst: &crate::ir::Instruction,\n    frame_name: &str,"
assert s.count(old) == 1
p.write_text(s.replace(old, new))

p = pathlib.Path("src/codegen/lower_inst/method_resolution.rs")
s = p.read_text()
old = '''        crate::ir::Op::MethodCall | crate::ir::Op::NullsafeMethodCall => {
            let crate::ir::Immediate::Data(method_id) = inst.immediate.as_ref()? else {
                return None;
            };
            let method = ctx.data.strings.get(method_id.as_raw() as usize)?;
            Some((
                format!("{class_name}->{method}"),
                inst.operands.iter().skip(1).copied().collect(),
            ))
        }'''
new = '''        crate::ir::Op::MethodCall | crate::ir::Op::NullsafeMethodCall => {
            let method = method_name_data(ctx, inst).ok()?;
            Some((
                format!("{class_name}->{method}"),
                inst.operands.iter().skip(1).copied().collect(),
            ))
        }'''
assert s.count(old) == 1
p.write_text(s.replace(old, new))
print("fixed")
